{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Oritavancin, a large glycosylated natural product, showed only 5% CSF/plasma penetration in a rabbit meningitis model, indicating poor CNS access; this transfers to the query's glycosylated polycyclic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Mithramycin, an aromatic polyketide glycoside, had a peak CSF:plasma ratio of 0.12 in monkeys and little material in normal brains, supporting poor CNS penetration for this class of glycosylated natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a cardiac glycoside, showed a very low CSF/plasma ratio of 0.01–0.03 in dogs, demonstrating that glycosylated natural products do not easily cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a glycosylated polyphenol, was the least concentrated compound in rat brain and could hardly pass the blood-brain barrier, consistent with poor CNS access for polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Orientin, a polar flavonoid glycoside, showed low brain levels after intravenous administration due to high polarity and difficulty crossing the blood-brain barrier, supporting the same direction for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, polar anthracycline glycoside with an aminosugar; all transferable experimental evidence from glycosylated natural products shows poor CNS penetration, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain, CSF, or plasma pharmacokinetic data for the query molecule itself; prediction relies on structurally related glycosylated natural products."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

